def choose_move(observation):
    w, h = observation.get('grid_width', 0), observation.get('grid_height', 0)
    x, y = observation.get('self_position', (0, 0))
    res = observation.get('resources', [])
    opps = observation.get('opponent_position', [])
    obstacles = set(observation.get('obstacles', []))
    scores = observation.get('scores', {})
    remaining = observation.get('remaining_resource_count', 0)
    my_score = scores.get('self', 0)
    opp_score = scores.get('opponent', 0)

    def dist(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    target = None
    min_d = float('inf')
    for r in res:
        p = r.get('position', None)
        if p and p not in obstacles:
            d = dist((x,y), p)
            if d < min_d:
                min_d = d
                target = p
    opp_p = opps if isinstance(opps, tuple) else (opps.get('x', 0), opps.get('y', 0))
    if isinstance(opp_p, dict):
        opp_p = (opp_p.get('x',0), opp_p.get('y',0))
    d_opp = dist((x,y), opp_p)
    if d_opp < min_d:
        target = opp_p

    dx = dy = 0
    if target:
        if target[0] > x:
            dx = 1
        elif target[0] < x:
            dx = -1
        elif target[1] > y:
            dy = 1
        elif target[1] < y:
            dy = -1
        nx, ny = x + dx, y + dy
        if (nx, ny) in obstacles or not (0 <= nx < w and 0 <= ny < h):
            dx = dy = 0
    return [dx, dy]
